export type RadarT = (key: string, vars?: Record<string, string | number>) => string;
export const RADAR_DICTS: Record<string, Dict> = { 'pt-BR': PT, en: EN, es: ES };
export function makeRadarT(locale: string): RadarT {
  const dict = RADAR_DICTS[locale] ?? PT;
  return (key, vars) => {
    const raw = dict[key] ?? PT[key] ?? key;
    return vars ? raw.replace(/\{(\w+)\}/g, (_m, k: string) => (k in vars ? String(vars[k]) : `{${k}}`)) : raw;
  };
}
